#include <stdlib.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

int compare_desc(const void *a, const void *b) {
    long long arg1 = *(const long long *)a;
    long long arg2 = *(const long long *)b;
    if (arg1 < arg2) return 1;
    if (arg1 > arg2) return -1;
    return 0;
}

long long dp[2][10005];
long long T[10005];

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        scanf("%lld", &T[i]);
    }

    qsort(T + 1, n, sizeof(long long), compare_desc);

    // dp[0][i] = 0 para todo i >= 0
    for (int i = 0; i <= n; i++) {
        dp[0][i] = 0;
    }

    for (int j = 1; j <= k; j++) {
        int cur = j & 1;
        int prev = 1 - cur;

        for (int i = 0; i <= n; i++) {
            dp[cur][i] = INF;
        }

        for (int i = 3 * j; i <= n; i++) {
            dp[cur][i] = dp[cur][i - 1];
            long long cost = (T[i - 1] - T[i]) * (T[i - 1] - T[i]);
            if (dp[prev][i - 2] != INF && dp[prev][i - 2] + cost < dp[cur][i]) {
                dp[cur][i] = dp[prev][i - 2] + cost;
            }
        }
    }

    printf("%lld\n", dp[k & 1][n]);

    return 0;
}
