#include <stdio.h>
#include <stdlib.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

static inline int cmp_desc(const void *a, const void *b) {
    int val_a = *(const int *)a;
    int val_b = *(const int *)b;
    if (val_a < val_b) return 1;
    if (val_a > val_b) return -1;
    return 0;
}

int T[10005];
long long dp[3005];
long long next_dp[3005];

int main() {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    for (int i = 1; i <= N; ++i) {
        if (scanf("%d", &T[i]) != 1) return 0;
    }

    qsort(T + 1, N, sizeof(int), cmp_desc);

    // dp[j] armazena o custo mínimo para formar j trios.
    // Inicialização: dp[0] = 0, dp[j] = INF para j > 0
    for (int j = 1; j <= K; ++j) {
        dp[j] = INF;
    }
    dp[0] = 0;

    // Usaremos três linhas ou alternância para dp[i-2], dp[i-1], dp[i].
    // Note que dp[i][j] depende de dp[i-1][j] e dp[i-2][j-1].
    // Vamos manter as linhas explicitamente em uma matriz de tamanho 3 x (K + 1).
    static long long memo[3][3005];
    for (int r = 0; r < 3; ++r) {
        for (int j = 0; j <= K; ++j) {
            memo[r][j] = INF;
        }
        memo[r][0] = 0;
    }

    for (int i = 1; i <= N; ++i) {
        int cur = i % 3;
        int prev1 = (i - 1) % 3;
        int prev2 = (i - 2 + 3) % 3;

        int max_j = i / 3;
        if (max_j > K) max_j = K;

        memo[cur][0] = 0;
        for (int j = 1; j <= max_j; ++j) {
            long long res = memo[prev1][j];

            if (memo[prev2][j - 1] != INF) {
                long long diff = (long long)T[i - 1] - T[i];
                long long cost = memo[prev2][j - 1] + diff * diff;
                if (cost < res) {
                    res = cost;
                }
            }
            memo[cur][j] = res;
        }
        for (int j = max_j + 1; j <= K; ++j) {
            memo[cur][j] = INF;
        }
    }

    printf("%lld\n", memo[N % 3][K]);

    return 0;
}
